import { z } from 'zod';
import { actorTypeSchema, idSchema, isoDateSchema } from '@devsync/validation';
import { PROTOCOL_VERSION } from './version';

/**
 * Every message exchanged over WebSocket (server <-> Bridge, server <-> dashboard)
 * is wrapped in this envelope. `id` is generated by the producer and is the
 * idempotency key: consumers must ignore an id they have already processed.
 */
export const actorSchema = z.object({
  type: actorTypeSchema,
  userId: idSchema.optional(),
  agentId: idSchema.optional(),
});
export type Actor = z.infer<typeof actorSchema>;

export const envelopeSchema = z.object({
  id: idSchema,
  type: z.string().regex(/^[a-z]+(\.[a-z]+)+$/, 'dotted lowercase event type'),
  version: z.string().default(PROTOCOL_VERSION),
  timestamp: isoDateSchema,
  teamId: idSchema,
  projectId: idSchema.optional(),
  actor: actorSchema,
  /** Server-assigned, monotonically increasing per team. Absent on client-produced events until persisted. */
  sequence: z.number().int().nonnegative().optional(),
  /** Correlates a response/event with the request or command that caused it. */
  correlationId: idSchema.optional(),
  payload: z.unknown(),
});
export type Envelope<P = unknown> = Omit<z.infer<typeof envelopeSchema>, 'payload'> & {
  payload: P;
};

/** Acknowledgement returned through the Socket.IO ack callback. */
export const ackSchema = z.discriminatedUnion('ok', [
  z.object({
    ok: z.literal(true),
    id: idSchema,
    sequence: z.number().int().optional(),
    duplicate: z.boolean().default(false),
  }),
  z.object({
    ok: z.literal(false),
    id: idSchema.optional(),
    code: z.string(),
    message: z.string(),
    retryable: z.boolean(),
  }),
]);
export type Ack = z.infer<typeof ackSchema>;
